mapper.sql:
FROM doctor_schedule ds JOIN doctor d ON d.id = ds.doctor_id JOIN department dp ON dp.id = ds.department_id WHERE ds.status = 1 AND ds.schedule_date >= CURRENT_DATE AND ds.booked_count < ds.total_count AND d.status = 1 AND d.deleted = 0
AND ds.department_id = #{departmentId}
AND ds.doctor_id = #{doctorId}
